                let groupStart = Math.floor((current - 1) / 5) * 5 + 1;
                let groupEnd = Math.min(groupStart + 4, total);
                let html = '';
                let GroupMembers = this.type === 'GroupMembers';
                let search = this.type === 'Search';
                if (search) {groupStart = Math.floor((current - 1) / 10) * 10 + 1; groupEnd = Math.min(groupStart + 9, total)};
