    async function getCsrfToken() {
        const res = await fetch("https://auth.roblox.com/v2/logout", {
            method: "POST",
            credentials: "include"
        });
        return res.headers.get("x-csrf-token");
    }
    async function getAPI(url) {
        return new Promise((resolve) => {
            GM_xmlhttpRequest({
                method: "GET",
                url,
                onload: (res) => resolve(JSON.parse(res.responseText)),
                onerror: () => resolve(null)
            });
        });
    }
    async function postAPI(url, data = {}, useCsrf = false, extraHeaders = {}) {
        return new Promise(async (resolve) => {
            let headers = {
                "Content-Type": "application/json",
                ...extraHeaders
            };
            if (useCsrf) {
                let csrf = await getCsrfToken();
                headers["X-CSRF-TOKEN"] = csrf;
            }
            GM_xmlhttpRequest({
                method:  "POST",
                url: url,
                credentials: "include",
                headers: headers,
                data: JSON.stringify(data),
                onload: (res) => resolve(JSON.parse(res.responseText)),
                onerror: () => resolve(null)
            });
        });
    }
    async function deleteAPI(url, data = {}, useCsrf = false, extraHeaders = {}) {
        return new Promise(async (resolve) => {
            let headers = {
                "Content-Type": "application/json",
                ...extraHeaders
            };
            if (useCsrf) {
                let csrf = await getCsrfToken();
                headers["X-CSRF-TOKEN"] = csrf;
            }
            GM_xmlhttpRequest({
                method:  "DELETE",
                url: url,
                credentials: "include",
                headers: headers,
                data: JSON.stringify(data),
                onload: (res) => resolve(JSON.parse(res.responseText)),
                onerror: () => resolve(null)
            });
        });
    }

