    async function favoriteGame(universeId, unfavorite = false) {
        let isFavorited = true;
        if (unfavorite === true) isFavorited = false;
        const csrf = await getCsrfToken();
        const res = await fetch(`https://games.roblox.com/v1/games/${universeId}/favorites`, {
            method: "POST",
            credentials: "include",
            headers: {
                "Content-Type": "application/json",
                "X-CSRF-TOKEN": csrf
            },
            body: JSON.stringify({
                isFavorited
            })
        });
        if (res.ok) {
            location.reload();
        } else {
            alert("Failed to favorite game.");
        }
    }
    async function favoriteAsset(userId, id, unfavorite = false) {
        const csrf = await getCsrfToken();
        const res = await fetch(`https://catalog.roblox.com/v1/favorites/users/${userId}/assets/${id}/favorite`, {
            method: unfavorite ? "DELETE" : "POST",
            credentials: "include",
            headers: {
                "Content-Type": "application/json",
                "X-CSRF-TOKEN": csrf
            },
            body: JSON.stringify({})
        });
        if (res.ok) {
            location.reload();
        } else {
            alert('Failed to favorite/unfavorite asset.');
        }
    }
    async function getFriends(id, size) {
        let friends = await getAPI(`https://friends.roblox.com/v1/users/${id}/friends`);
        if (size) friends = friends.data.slice(0, size);
        let ids = friends.map(f => f.id);
        let profiles = await getProfiles(ids);
        let status = await getUserStatus(ids);
        let bc = await Promise.all(friends.map(friend => getUserBC(friend.id)));
        return friends.map((friend, i) => ({
            ...friend,
            name: profiles.data[i].name || friend.name || '',
            status: status.userPresences[i],
            hasbc: bc[i],
        }));
    }
