        async function getFeed() {
            let feed = await getAPI(`https://notifications.roblox.com/v2/stream-notifications/get-recent?startIndex=0&maxRows=20`);
            let items = [];
            for (let n of feed){
                let type = n.content.notificationType;
                /*if (type === "GameUpdate"){
                    const gameId = n.content.states.default.visualItems.button[1].actions[0].path.replace('roblox://placeId=','');
                    items.push({
                        type: "game",
                        id: gameId,
                        title: n.content.states.default.visualItems.textBody[0].title.text,
                        desc: n.content.states.default.visualItems.textBody[0].label.text,
                        date: new Date(n.eventDate),
                        url: `/games/${gameId}/`
                    });
                }*/
                if (type === "GroupShout"){
                    let id = n.content.states["notifications-on"].visualItems.button[1].actions[0].path.replace('roblox://navigation/group?groupId=','');
                    let title = SplitShoutTitle(n.content.states["notifications-on"].visualItems.textBody[0].title.text);
                    items.push({
                        type: "groupAnnouncement",
                        id,
                        title: title.name,
                        desc: n.content.states["notifications-on"].visualItems.textBody[0].label.text,
                        author: title.author,
                        date: new Date(n.eventDate),
                        url: `/Groups/group.aspx?gid=${id}`
                    });
                }
            }
            return items;
        }
