    // Inbox Page
    async function createInboxPager(tab) {
        let p = createPager({
            id: 0,
            type: 'Search',
            pageSize: 20,
            container: '#ctl00_ctl00_cphRoblox_cphMyRobloxContent_InboxGridView tbody',
            pagerContainer: '#pager',
            fetchPage: (c) => getAPI(`https://privatemessages.roblox.com/v1/messages?pageNumber=${c}&pageSize=20&messageTab=${tab}`),
            parsePage: (d,p) => {
                p.knownTotalPages = d.totalPages;
                let nextCursor = d.pageNumber + 1 >= d.totalPages ? null : d.pageNumber + 1;
                return {items:d.collection,nextCursor:null};
            },
            renderItems: async (d,p) => {
                $('#Processing').hide();
                if (!d) {
                    p.$container.replaceWith(`<div id="EmptyInbox" style="text-align: center">You have no messages in your Inbox.</div>`);
                    return;
                };
                if (p.totalPages > 1) p.$pagerContainer.show();
                let html;
                if (modernLayout) html = d.map(m => `<tr class="${m.sender.id === 1 ? 'SystemAlertMessage' : m.isRead === true ? 'InboxRow' : 'InboxRow_Unread'}"><td class="Select" style="width: 39px" align="left"><input class="checkbox" type="checkbox"></td><td class="From" style="width: 209px" align="left"><a class="FromText" href="${m.sender.id === 1 ? '#' : `/User.aspx?ID=${m.sender.id}`}" title="${m.sender.id === 1 ? 'ROBLOX [System Message]' : `Visit ${m.sender.name}'s Home Page`}">${m.sender.id === 1 ? 'ROBLOX [System Message]' : message.sender.name}</a></td><td class="Subject" style="width: 300px" align="left"><div style="width:300px;overflow:hidden"><a class="SubjectText" href="/PrivateMessage.aspx?MessageID=${m.id}">${m.subject}</a></div></td><td class="Date" align="right"><a class="DateText">${messagesFormat(m.created)}</a></td><td class="Expires" align="right" style="display: none"><a></a></td></tr>`);
                else html = d.map(m => `<tr class="${m.sender.id === 1 ? 'SystemAlertMessage' : m.isRead === true ? 'InboxRow' : 'InboxRow_Unread'}"><td><span style="display:inline-block;width:25px;"><input id="ctl00_ctl00_cphRoblox_cphMyRobloxContent_InboxGridView_ctl01_DeleteCheckbox" type="checkbox" name="ctl00$ctl00$cphRoblox$cphMyRobloxContent$InboxGridView$ctl01$DeleteCheckbox"></span></td><td align="left"><a href="/PrivateMessage.aspx?MessageID=${m.id}" style="display:inline-block;width:300px;">${m.subject}</a></td><td align="left"><a id="ctl00_ctl00_cphRoblox_cphMyRobloxContent_InboxGridView_ctl01_hlAuthor" title="${m.sender.id === 1 ? 'ROBLOX [System Message]' : `Visit ${m.sender.name}'s Home Page`}" href="${m.sender.id === 1 ? '#' : `/User.aspx?ID=${m.sender.id}`}" style="display:inline-block;width:175px;">${m.sender.id === 1 ? 'ROBLOX [System Message]' : m.sender.name}</a></td><td align="left">${groupFormat(m.created)}</td></tr>`);
                p.$container.find('tr.SystemAlertMessage, tr.InboxRow, tr.InboxRow_Unread').remove();
                p.$container.append(html);
            }
        });
        await p.init();
    }
