            if (p.components.Actions.buttons.some(btn => btn.type === 'AddFriend') && classic) $('p:has(> #ctl00_cphRoblox_rbxUserPane_rbxPublicUser_hlSendMessage)').next('p').append($(`<a id="ctl00_cphRoblox_rbxUserPane_rbxPublicUser_hlAddFriend" href="/My/FriendInvitation.aspx?RecipientID=${userID}">Send Friend Request</a>`));
