        async function loadSets() {
            let p = createPager({
                id: userID,
                type: 'so',
                pageSize: 9,
                container: '#OwnedSetsContainerDiv #SetsItemContainer',
                pagerContainer: '#OwnedSetsContainerDiv #SetsPagerContainer',
                fetchPage: () => getAPI(`https://sets.pizzaboxer.xyz/api/users/${userID}`),
                parsePage: (d) => {
                    return {items:d.owned,nextCursor:null};
                },
                renderItems: async (d,p) => {
                    if (d.length) {
                        let ids = d.map(s => s.imageAssetId);
                        let imgs = getThumbnail(ids,'Asset','75x75');
                        let sets = d.map(s => `<div style="display: block;" class="TiledSets"><div class="AssetThumbnail"><img class="set ${s.imageAssetId}" src="${di.Spinners.spinner16x16}"></div><div class="AssetDetails"><div class="AssetName"><a href="/My/Sets.aspx?id=${s.id}">${s.name}</a></div><div class="AssetCreator"><span class="Label">Creator:&nbsp;</span><span class="Detail"><a href="/User.aspx?id=${s.creatorId}">${s.creatorName}</a></span></div></div></div>`).join('');
                        p.$container.html(`${sets}<div style="clear:both;"></div>`);
                        truncateAll('.TiledSets .AssetName a', 90);
                        truncateAll('.TiledSets .AssetCreator .Detail a', 55);
                        imgs = await imgs;
                        imgs.forEach(({targetId,imageUrl}) => $(`.TiledSets .AssetThumbnail .set.${targetId}`).attr('src',imageUrl).css('width','75px').css('height','75px'));
                    } else {
                        p.$container.html(`<div class="NoSets">This user has no sets.</div>`);
                        p.$pagerContainer.empty();
                    };
                }
            });
            let p2 = createPager({
                id: userID,
                type: 'ss',
                pageSize: 9,
                container: '#SubscribedSetsContainerDiv #SubscribedSetsItemContainer',
                pagerContainer: '#SubscribedSetsContainerDiv #SubscribedSetsPagerContainer',
                fetchPage: () => getAPI(`https://sets.pizzaboxer.xyz/api/users/${userID}`),
                parsePage: (d) => {
                    return {items:d.subscribed,nextCursor:null};
                },
                renderItems: async (d,p) => {
                    if (d.length) {
                        let ids = d.map(s => s.imageAssetId);
                        let imgs = getThumbnail(ids, 'Asset', '75x75');
                        let sets = d.map(s => `<div style="display: block;" class="TiledSets"><div class="AssetThumbnail"><img class="set ${s.imageAssetId}" src="${di.Spinners.spinner16x16}"></div><div class="AssetDetails"><div class="AssetName"><a href="/My/Sets.aspx?id=${s.id}">${s.name}</a></div><div class="AssetCreator"><span class="Label">Creator:&nbsp;</span><span class="Detail"><a href="/User.aspx?id=${s.creatorId}">${s.creatorName}</a></span></div></div></div>`).join('');
                        p.$container.html(`${sets}<div style="clear:both;"></div>`);
                        truncateAll('.TiledSets .AssetName a', 90);
                        truncateAll('.TiledSets .AssetCreator .Detail a', 55);
                        imgs = await imgs;
                        imgs.forEach(({targetId,imageUrl}) => $(`.TiledSets .AssetThumbnail .set.${targetId}`).attr('src',imageUrl).css('width','75px').css('height','75px'));
                    } else {
                        p.$container.html(`<div class="NoSets">This user is not subscribed to any sets.</div>`);
                        p.$pagerContainer.empty();
                    };
                }
            });
            if (con.setsbox && modernLayout) {
                $(document).on('click','#ToggleBetweenOwnedSubscribedSets',function() {
                    if ($('#SubscribedSetsContainerDiv[style]').length > 0) {
                        $(this).text(`View Owned`);
                        $('#SubscribedSetsContainerDiv').removeAttr('style');
                        $('#OwnedSetsContainerDiv').hide();
                    } else {
                        $(this).text(`View Subscribed`);
                        $('#SubscribedSetsContainerDiv').hide();
                        $('#OwnedSetsContainerDiv').removeAttr('style');
                    };
                });
                await Promise.all(p.init(),p2.init());
            };
        };
