                $('#ctl00_ctl00_cphRoblox_cphMyRobloxContent_LeftArmSelector').css('background-color', `#${c.leftArmColor3}`);
                $('#ctl00_ctl00_cphRoblox_cphMyRobloxContent_RightLegSelector').css('background-color', `#${c.rightLegColor3}`);
                $('#ctl00_ctl00_cphRoblox_cphMyRobloxContent_LeftLegSelector').css('background-color', `#${c.leftLegColor3}`);
                await postAPI(`https://avatar.roblox.com/v2/avatar/set-wearing-assets`, {assets: [...p.assets]}, true);
                await updateBodyColors();
                await redraw();
