        async function loadPlaceImg() {
            if (modernLayout) {
                let details = await getGamePlaceDetails(gameID);
                let imgs = await getAPI(`https://games.roblox.com/v2/games/${details[0].universeId}/media`);
                let imgIds = imgs.data.filter(a => a.assetType === 'Image').map(img => img.imageId);
                let vidIds = imgs.data.filter(a => a.assetType === 'YouTubeVideo').map(img => img.videoHash);
                let img = getAPI(`https://thumbnails.roblox.com/v1/games/${details[0].universeId}/thumbnails?thumbnailIds=${imgIds}&size=480x270&format=Png&isCircular=false`);
                img.then(d => {
                    $('#ctl00_cphRoblox_rbxRichMediaThumbDisplay_rbxGalleryAssetThumbnail_rbxAssetImage img:first-child').attr('src', d.data[0].imageUrl).parent().find('img[src="/Thumbs/ProgressIndicator.gif"]').remove();
                });
                if (imgs.data.length > 1) {
                    let html = imgs.data.map((img, length) => `<div class="divSmallGalleryItem ${length === 0 ? `SelectedYouTubeGalleryIcon` : ''}" placemediaitemid="${img.imageId}"><div class="smallGalleryThumbItem">${img.assetType === 'YouTubeVideo' ? `<div id="divYouTubePlayer_ytPlayerId" class="divYouTubeVideoPlayer" style="z-index: -1"><iframe width="120" height="70" src="https://www.youtube.com/embed/${img.videoHash}" title="YouTube video player" frameborder="0" allow="accelerometer; autoplay; encrypted-media; gyroscope; modestbranding; web-share" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe></div>` : `<a id="ctl00_cphRoblox_rbxRichMediaThumbDisplay_ItemMediaGallery_ctl01_ctl01_rbxAssetImage" title="${details.name}_Image" style="display:inline-block;height:70px;width:120px;cursor:pointer;"><img src="/Thumbs/blank.gif" height="70" width="120" border="0" onerror="return Roblox.Controls.Image.OnError(this)" alt="${details.name}_Image"></a>`}</div><div class="youTubeVideoOverlay"></div></div>`).join('');
                    $('#ItemThumbnail').parent().append(`<div id="divSmallGalleryItemBox"><div id="divSmallGalleryScrollContainer">${html}</div><script type="text/javascript">
                    var autotransition = true;
                    var muted = true;
                    function autotransitionNext() {
                        if (!autotransition) return;
                        var next = $('.SelectedYouTubeGalleryIcon').next();
                        if (next.length > 0) transitionGallery(next);
                    }
                    function transitionGallery(divSmallGalleryItem) {
                        var thisItem = $(divSmallGalleryItem).find('.smallGalleryThumbItem');
                        var youTubeVideoItem = thisItem.find('.divYouTubeVideoPlayer');
                        if (youTubeVideoItem.length != 0) {
                            thisItem = $(youTubeVideoItem.children()[0]).clone();
                            if (thisItem.is("object") || thisItem.is("iframe")) {
                                thisItem.height('230');
                                thisItem.attr('Height', '230px'); // Iframes need height and width?
                                thisItem.width('420');
                                thisItem.attr('Width', '420px');
                                thisItem.attr('src', thisItem.attr('src') + '?autoplay=1&mute=1');
                            }
                            $('.PlaceThumbOverlay').fadeOut('slow');
                        } else {
                            var assetImageChild = thisItem.find('img')[0]; // Asset Image
                            thisItem = $(assetImageChild).clone();
                            thisItem.height('230');
                            thisItem.width('420');
                            setTimeout(function() { autotransitionNext(); }, 5000);
                            $('.PlaceThumbOverlay').fadeIn('slow');
                        }
                        // Clear our any existing transitions incase they're going fast through them.
                        $('#divTransitionLargeGalleryItem').remove();
                        $('#ItemThumbnail').append("<div id='divTransitionLargeGalleryItem' style='display: none; position: absolute;'>");
                        $('#divTransitionLargeGalleryItem').append(thisItem);
                        $('#divTransitionLargeGalleryItem').fadeIn('slow', function () { });
                        $('#bigGalleryThumbItem').fadeOut('slow', function () { $('#divTransitionLargeGalleryItem').attr('id', 'bigGalleryThumbItem'); $(this).remove(); });
                        $('.divSmallGalleryItem').removeClass('SelectedYouTubeGalleryIcon');
                        $(divSmallGalleryItem).addClass('SelectedYouTubeGalleryIcon');
                    }
                    $('.youTubeVideoOverlay').click(function () {
                        // When they click on a small gallery image, we need to put it in the big gallery spot
                        autotransition = false;
                        muted = false;
                        transitionGallery($(this).parent());
                    });
                    $(function() {
                        if (true) $('.PlaceThumbOverlay').hide();
                        else setTimeout(function () { autotransitionNext(); }, 5000);
                    });</script></div>`);
                    img.then(data => {
                        data.data.forEach(({targetId,imageUrl}) => {
                            $(`.divSmallGalleryItem[placemediaitemid="${targetId}"] img`).attr('src', imageUrl);
                        });
                    });
                    let width = 0;
                    $('#divSmallGalleryScrollContainer').children().each(function() {
                        width += $(this).outerWidth(true);
                    });
                    $('#divSmallGalleryScrollContainer').width(width);
                };
            } else lImg2(getThumbnail(gameID,'Asset','480x270'),'game');
        };
